 int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}void base(String name){ScrollView s=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);body.setLayoutDirection(1);body.setBackgroundColor(0xfff7f8fc);body.setPadding(dp(18),dp(20),dp(18),dp(20));s.addView(body);setContentView(s);body.setOnApplyWindowInsetsListener((v,i)->{android.graphics.Insets bars=i.getInsets(android.view.WindowInsets.Type.systemBars());v.setPadding(dp(18),bars.top+dp(16),dp(18),bars.bottom+dp(16));return i;});label(name,24);}
 TextView label(String s,int n){TextView t=new TextView(this);t.setText(s);t.setTextSize(n);t.setTypeface(font);t.setTextColor(0xff31394f);t.setPadding(0,dp(7),0,dp(7));body.addView(t);return t;}void btn(String s,Runnable action){Button b=new Button(this);b.setTypeface(font);b.setText(s);b.setTextColor(0xff5948c8);body.addView(b);b.setOnClickListener(v->action.run());}EditText field(String s,String value){label(s,13);EditText e=new EditText(this);e.setTypeface(font);e.setTextSize(15);e.setInputType(131073);e.setText(value);body.addView(e);return e;}Spinner select(String s,String[] values,int n){label(s,13);Spinner x=new Spinner(this);x.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,values));x.setSelection(n);body.addView(x);return x;}void err(Exception e){new AlertDialog.Builder(this).setMessage(e.getMessage()==null?"تعذر إتمام العملية":e.getMessage()).setPositiveButton("حسنًا",null).show();}
 void list(){draft=null;getPreferences(0).edit().remove("draft").apply();base("إدارة نشاط البرامج");if(owner>0)label("العميل: "+store.lead(owner).optString("name"),18);label("اشتراكات وتطوير ودعم وجلسات مستقلة لكل عميل",14);btn("+ طلب أو اشتراك جديد",this::newWork);btn("دليل البرامج والباقات",this::catalog);btn(today?"عرض كل الطلبات":"المستحق اليوم والمتأخر",()->{today=!today;list();});Spinner f=select("نوع الطلب",new String[]{"كل الأنواع","الاشتراكات","التطوير","الدعم الفني","التجارب والتدريب"},filter);f.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,android.view.View v,int n,long id){if(n!=filter){filter=n;list();}}});int count=0;for(JSONObject row:store.query("SELECT * FROM softwareRequests "+(owner>0?"WHERE leadId="+owner:"")+" ORDER BY id DESC")){try{JSONObject q=new JSONObject(row.getString("data"));if(filter>0&&!q.optString("type").equals(SoftwareWork.TYPES[filter-1]))continue;boolean due=false;StringBuilder reminders=new StringBuilder();for(String kind:SoftwareWork.REMINDERS){String date=SoftwareWork.due(q,kind);if(!date.isEmpty()&&date.compareTo(java.time.LocalDate.now().toString())<=0){due=true;reminders.append(SoftwareWork.reminderLabel(kind)).append(": ").append(date).append("\n");}}if(today&&!due)continue;label(q.optString("title"),20);label(store.lead(row.optLong("leadId")).optString("name")+" • "+SoftwareWork.label(q.optString("type"))+" • "+SoftwareWork.statuses(q.optString("type"))[q.optInt("status")],13);if(reminders.length()>0)label(reminders.toString(),14);JSONObject details=q.optJSONObject("details");if(details!=null&&SoftwareWork.value(details.optString("amount")).signum()>0)label("المتبقي: "+QuoteMath.money(SoftwareWork.value(details.optString("amount")).subtract(SoftwareWork.value(details.optString("paid"))))+" ريال",14);btn("فتح التفاصيل",()->{try{draft=store.softwareRequest(row.optLong("id"));editor();}catch(Exception e){err(e);}});count++;}catch(Exception e){err(e);}}if(count==0)label("لا توجد طلبات في هذا العرض",17);btn("رجوع",this::finish);}
 void newWork(){ArrayList<JSONObject> clients=store.query("SELECT * FROM leads WHERE business='software' ORDER BY name");if(owner>0){startNew(owner);return;}if(clients.isEmpty()){err(new IllegalArgumentException("أضف عميلًا إلى نشاط البرامج أولًا"));return;}String[] names=new String[clients.size()];for(int i=0;i<names.length;i++)names[i]=clients.get(i).optString("name");new AlertDialog.Builder(this).setTitle("اختر العميل").setItems(names,(d,n)->startNew(clients.get(n).optLong("id"))).show();}
 void startNew(long client){if(!store.lead(client).optString("business").equals("software")){err(new IllegalArgumentException("العميل لا ينتمي لنشاط البرامج"));return;}new AlertDialog.Builder(this).setTitle("نوع الطلب الجديد").setItems(SoftwareWork.LABELS,(d,n)->{try{JSONObject seed=new JSONObject();try{JSONObject old=new JSONObject(store.lead(client).optString("requestDetails","{}"));JSONObject prior=old.optJSONObject("software");if(prior!=null){for(String key:new String[]{"program","plan","platform","needs"})seed.put(key,prior.optString(key));if(n==0)seed.put("endDate",prior.optString("subscriptionEnd"));if(n==3)seed.put("sessionDate",prior.optString("demoDate"));}}catch(Exception ignored){}draft=new JSONObject().put("leadId",client).put("type",SoftwareWork.TYPES[n]).put("status",0).put("priority",1).put("details",seed).put("followTime","09:00");editor();}catch(Exception e){err(e);}}).show();}
 void editor(){try{inputs.clear();snapshot=draft.optLong("id")>0?store.softwareRequest(draft.optLong("id")).toString():"";base(SoftwareWork.label(draft.optString("type")));label("العميل: "+store.lead(draft.optLong("leadId")).optString("name"),17);title=field("عنوان الطلب *",draft.optString("title"));state=select("الحالة",SoftwareWork.statuses(draft.optString("type")),draft.optInt("status"));priority=select("الأولوية",new String[]{"منخفضة","عادية","عالية","عاجلة"},draft.optInt("priority",1));JSONObject d=draft.getJSONObject("details");for(String[] f:SoftwareWork.fields(draft.optString("type"))){EditText e=field(f[1],d.optString(f[0],f[0].equals("renewDays")?"7":""));inputs.put(f[0],e);if(f[0].equals("amount")||f[0].equals("paid"))e.setInputType(8194);if(f[0].equals("renewDays"))e.setInputType(2);if(f[0].endsWith("Date"))dateButton(e);}btn("اختيار برنامج من الدليل",()->pickProduct());follow=field("موعد متابعة مستقل YYYY-MM-DD",draft.optString("followUp"));dateButton(follow);time=field("وقت التنبيه HH:mm",draft.optString("followTime","09:00"));btn("اختيار وقت التنبيه",()->new TimePickerDialog(this,(v,h,m)->time.setText(String.format(java.util.Locale.US,"%02d:%02d",h,m)),9,0,true).show());label("تنبيهات تلقائية للتجديد والدفعات والتسليم والجلسات عند تحديد تواريخها. الطلب المكتمل أو الملغى لا يرسل تنبيهات.",13);if(inputs.containsKey("amount"))btn("حساب المتبقي",()->{try{capture();JSONObject details=draft.getJSONObject("details");label("المتبقي: "+QuoteMath.money(SoftwareWork.value(details.optString("amount")).subtract(SoftwareWork.value(details.optString("paid"))))+" ريال",18);}catch(Exception e){err(e);}});btn("حفظ الطلب",()->save());if(draft.optLong("id")>0)btn("حذف الطلب",()->new AlertDialog.Builder(this).setMessage("حذف هذا الطلب نهائيًا؟").setNegativeButton("إلغاء",null).setPositiveButton("حذف",(dialog,w)->{store.getWritableDatabase().delete("softwareRequests","id=?",new String[]{String.valueOf(draft.optLong("id"))});getSystemService(NotificationManager.class).cancel("software",(int)draft.optLong("id"));list();Reminders.schedule(this);}).show());btn("العودة إلى القائمة",this::back);}catch(Exception e){err(e);}}
 void dateButton(EditText entry){btn("اختيار التاريخ",()->{java.time.LocalDate n=java.time.LocalDate.now();new DatePickerDialog(this,(v,y,m,d)->entry.setText(java.time.LocalDate.of(y,m+1,d).toString()),n.getYear(),n.getMonthValue()-1,n.getDayOfMonth()).show();});}
 void capture()throws Exception{draft.put("title",title.getText().toString().trim()).put("status",state.getSelectedItemPosition()).put("priority",priority.getSelectedItemPosition()).put("followUp",follow.getText().toString().trim()).put("followTime",time.getText().toString().trim());JSONObject d=draft.getJSONObject("details");for(String key:inputs.keySet())d.put(key,inputs.get(key).getText().toString().trim());}
 boolean save(){try{capture();store.saveSoftware(draft);snapshot=draft.toString();getPreferences(0).edit().putString("draft",snapshot).apply();getSystemService(NotificationManager.class).cancel("software",(int)draft.optLong("id"));Reminders.schedule(this);Toast.makeText(this,"حُفظ الطلب",0).show();return true;}catch(Exception e){err(e);return false;}}
 void pickProduct(){ArrayList<JSONObject> rows=store.query("SELECT * FROM softwareProducts ORDER BY id DESC");String[] names=new String[rows.size()];for(int i=0;i<rows.size();i++)try{JSONObject d=new JSONObject(rows.get(i).getString("data"));names[i]=d.optString("name")+" • "+d.optString("plan");}catch(Exception ignored){}new AlertDialog.Builder(this).setTitle("البرامج والباقات").setItems(names,(dialog,n)->{try{JSONObject d=new JSONObject(rows.get(n).getString("data"));if(inputs.containsKey("program"))inputs.get("program").setText(d.optString("name"));if(inputs.containsKey("plan"))inputs.get("plan").setText(d.optString("plan"));}catch(Exception e){err(e);}}).show();}
 void catalog(){base("دليل البرامج والباقات");btn("+ إضافة برنامج أو باقة",()->product(new JSONObject(),0));for(JSONObject row:store.query("SELECT * FROM softwareProducts ORDER BY id DESC"))try{JSONObject p=new JSONObject(row.getString("data"));label(p.optString("name")+" • "+p.optString("plan"),19);label(p.optString("price")+" ريال • "+p.optString("period"),14);btn("تعديل",()->product(p,row.optLong("id")));}catch(Exception e){err(e);}btn("عودة إلى الطلبات",this::list);}
 void product(JSONObject data,long id){LinearLayout previous=body,f=new LinearLayout(this);f.setOrientation(1);body=f;EditText name=field("اسم البرنامج *",data.optString("name")),plan=field("الباقة",data.optString("plan")),price=field("السعر المرجعي (ريال)",data.optString("price")),period=field("الدورة: شهري / سنوي / مرة واحدة",data.optString("period")),notes=field("وصف المميزات",data.optString("notes"));body=previous;ScrollView scroll=new ScrollView(this);scroll.addView(f);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("برنامج / باقة").setView(scroll).setNegativeButton("إلغاء",null).setPositiveButton("حفظ",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(w->{try{if(name.getText().toString().trim().isEmpty())throw new IllegalArgumentException("أدخل اسم البرنامج");SoftwareWork.value(price.getText().toString());JSONObject p=new JSONObject().put("name",name.getText().toString()).put("plan",plan.getText().toString()).put("price",price.getText().toString()).put("period",period.getText().toString()).put("notes",notes.getText().toString());ContentValues row=new ContentValues();row.put("data",p.toString());if(id==0)store.getWritableDatabase().insertOrThrow("softwareProducts",null,row);else store.getWritableDatabase().update("softwareProducts",row,"id=?",new String[]{String.valueOf(id)});dialog.dismiss();catalog();}catch(Exception e){err(e);}}));dialog.show();}
